    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    # Fill gaps in horizontal alternating patterns.
    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c] == bg and grid[r][c-1] == fg and grid[r][c+1] == fg:
                out[r][c] = 2

    # Fill vertical gaps only when the surrounding marks form a separated run,
    # rather than adjacent foreground marks.
    for r in range(1, h - 1):
        for c in range(w):
            if grid[r][c] != bg or grid[r-1][c] != fg or grid[r+1][c] != fg:
                continue
            if (r >= 2 and grid[r-2][c] == fg) or (r+2 < h and grid[r+2][c] == fg):
                continue
            out[r][c] = 2
    return out
